// Retires the service worker left behind by the old Chirpy site.
// Chirpy registered /sw.min.js with a cache-first strategy, so returning visitors kept
// seeing the old pages. Browsers re-check this URL on the next visit, install this
// version, which deletes Chirpy's caches, unregisters itself and reloads open tabs.
self.addEventListener('install', () => self.skipWaiting());

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.filter((k) => k.startsWith('chirpy-')).map((k) => caches.delete(k)));
    await self.registration.unregister();
    const tabs = await self.clients.matchAll({ type: 'window' });
    tabs.forEach((tab) => tab.navigate(tab.url));
  })());
});
